// ❌ DANGEROUS: HashMap in a multi-threaded context
Map<String, Integer> unsafeMap = new HashMap<>();
// Two threads calling put() simultaneously can:
// 1. Cause an infinite loop during resize (Java 7, circular link)
// 2. Silently lose one update (Java 8+)
// 3. Return stale/null values

// ✅ SAFE OPTION 1: ConcurrentHashMap (recommended for high concurrency)
Map<String, Integer> safeMap = new ConcurrentHashMap<>();
safeMap.put("account-1", 1000); // Thread-safe
safeMap.computeIfAbsent("account-2", k -> 500); // Atomic compound op

// Atomic increment - avoids a separate get+put race condition
safeMap.merge("account-1", 100, Integer::sum);

// ✅ SAFE OPTION 2: Collections.synchronizedMap (simpler, but locks whole map)
Map<String, Integer> syncMap = Collections.synchronizedMap(new HashMap<>());
// ⚠️ Even with synchronizedMap, compound operations like
// 'if not present then put' are NOT atomic — still need external sync!

// The correct way for atomic conditional put:
concurrentMap.putIfAbsent("key", value); // Atomic in ConcurrentHashMap

// Java 8 internal structure:
// Bucket 0: [A -> 10] -> [D -> 40]  (only bucket 0 locked when writing here)
// Bucket 1: [B -> 20]               (bucket 1 can be written concurrently)
// Bucket 2: [C -> 30]               (bucket 2 can be written concurrently)
